package com.example.takura.media.infrastructure;
import com.example.takura.media.application.MalwareScanner;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.Locale;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;
@Component @Profile("!test-controlled-scan") public class ClamAvScanner implements MalwareScanner {private final String host;private final int port,timeout;public ClamAvScanner(@Value("${takura.scanner.host:127.0.0.1}")String host,@Value("${takura.scanner.port:3310}")int port,@Value("${takura.scanner.timeout-ms:10000}")int timeout){this.host=host;this.port=port;this.timeout=timeout;}
 @Override public Result scan(byte[] bytes){String version=version();if(version==null||!fresh(version))return new Result(Result.Status.UNAVAILABLE,version);try(Socket socket=connect()){var out=new DataOutputStream(socket.getOutputStream());out.write("zINSTREAM\0".getBytes(StandardCharsets.US_ASCII));for(int offset=0;offset<bytes.length;){int length=Math.min(8192,bytes.length-offset);out.writeInt(length);out.write(bytes,offset,length);offset+=length;}out.writeInt(0);out.flush();String response=read(socket);if(response.contains(" FOUND"))return new Result(Result.Status.REJECTED,version);if(response.contains(" OK"))return new Result(Result.Status.CLEAN,version);return new Result(Result.Status.UNKNOWN,version);}catch(Exception unavailable){return new Result(Result.Status.UNAVAILABLE,version);}}
 private String version(){try(Socket socket=connect()){socket.getOutputStream().write("zVERSION\0".getBytes(StandardCharsets.US_ASCII));return read(socket).trim();}catch(Exception unavailable){return null;}}
 private Socket connect()throws IOException{var socket=new Socket();socket.connect(new InetSocketAddress(host,port),timeout);socket.setSoTimeout(timeout);return socket;}
 private static String read(Socket socket)throws IOException{var input=new BufferedInputStream(socket.getInputStream());var bytes=new ByteArrayOutputStream();for(int value;(value=input.read())!=-1&&value!=0;){bytes.write(value);if(value=='\n')break;}return bytes.toString(StandardCharsets.UTF_8);}
 private static boolean fresh(String version){try{String date=version.substring(version.lastIndexOf('/')+1).trim();Instant signed=LocalDateTime.parse(date,DateTimeFormatter.ofPattern("EEE MMM d HH:mm:ss yyyy",Locale.ENGLISH)).toInstant(ZoneOffset.UTC);Instant now=Instant.now();return !signed.isBefore(now.minus(Duration.ofDays(7)))&&!signed.isAfter(now.plus(Duration.ofDays(1)));}catch(Exception invalid){return false;}}
}
